        self.text = text
        self.textFormat = textFormat
        self.clientMessageId = clientMessageId
    }

    private enum CodingKeys: String, CodingKey {
        case toUserId = "touserid"
        case text = "text"
        case textFormat = "textformat"
        case clientMessageId = "clientmsgid"
