        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.toUserId = container.decodeLenient(Int.self, forKey: .toUserId) ?? 0
        self.text = container.decodeLenient(String.self, forKey: .text) ?? ""
        self.textFormat = container.decodeLenient(Int.self, forKey: .textFormat) ?? 0
        self.clientMessageId = container.decodeLenient(String.self, forKey: .clientMessageId)
