public struct MoodleSentMessage: Codable, Hashable, Sendable {
    /// test this to know if it succeeds: id of the created message if it succeeded, -1 when failed
    public var messageId: Int
    /// your own id for the message
    public var clientMessageId: String?
    /// error message - if it failed
    public var errorMessage: String?
    /// The text of the message
    public var text: String?
    /// The timecreated timestamp for the message
    public var timeCreated: Int64?
    /// The conversation id for this message
    public var conversationId: Int?
    /// The user id who sent the message
    public var userIdFrom: Int?
    /// If the user can delete messages in the conversation for all users
    public var canDeleteMessagesForAllUsers: Bool

    public init(
        messageId: Int = 0,
        clientMessageId: String? = nil,
        errorMessage: String? = nil,
        text: String? = nil,
        timeCreated: Int64? = nil,
        conversationId: Int? = nil,
        userIdFrom: Int? = nil,
        canDeleteMessagesForAllUsers: Bool = false
    ) {
        self.messageId = messageId
        self.clientMessageId = clientMessageId
        self.errorMessage = errorMessage
        self.text = text
        self.timeCreated = timeCreated
        self.conversationId = conversationId
        self.userIdFrom = userIdFrom
        self.canDeleteMessagesForAllUsers = canDeleteMessagesForAllUsers
    }

    private enum CodingKeys: String, CodingKey {
        case messageId = "msgid"
        case clientMessageId = "clientmsgid"
        case errorMessage = "errormessage"
        case text = "text"
        case timeCreated = "timecreated"
        case conversationId = "conversationid"
        case userIdFrom = "useridfrom"
        case canDeleteMessagesForAllUsers = "candeletemessagesforallusers"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.messageId = container.decodeLenient(Int.self, forKey: .messageId) ?? 0
        self.clientMessageId = container.decodeLenient(String.self, forKey: .clientMessageId)
        self.errorMessage = container.decodeLenient(String.self, forKey: .errorMessage)
        self.text = container.decodeLenient(String.self, forKey: .text)
        self.timeCreated = container.decodeLenient(Int64.self, forKey: .timeCreated)
        self.conversationId = container.decodeLenient(Int.self, forKey: .conversationId)
        self.userIdFrom = container.decodeLenient(Int.self, forKey: .userIdFrom)
        self.canDeleteMessagesForAllUsers = container.decodeLenient(Bool.self, forKey: .canDeleteMessagesForAllUsers) ?? false
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(messageId, forKey: .messageId)
        try container.encode(clientMessageId, forKey: .clientMessageId)
        try container.encode(errorMessage, forKey: .errorMessage)
        try container.encode(text, forKey: .text)
        try container.encode(timeCreated, forKey: .timeCreated)
        try container.encode(conversationId, forKey: .conversationId)
        try container.encode(userIdFrom, forKey: .userIdFrom)
        try container.encode(canDeleteMessagesForAllUsers, forKey: .canDeleteMessagesForAllUsers)
    }
}

